import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Architecture","description":"How Proxmox VM Autoscale is put together — components, control flow, threading model, state, and the extension points that exist.","frontmatter":{"title":"Architecture","description":"How Proxmox VM Autoscale is put together — components, control flow, threading model, state, and the extension points that exist.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/reference/architecture.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/reference/architecture.html"}],["meta",{"property":"og:title","content":"Architecture"}],["meta",{"property":"og:description","content":"How Proxmox VM Autoscale is put together — components, control flow, threading model, state, and the extension points that exist."}]]},"headers":[],"relativePath":"reference/architecture.md","filePath":"reference/architecture.md","lastUpdated":null}'),o={name:"reference/architecture.md"};function i(c,e,r,l,p,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Five Python modules, roughly 1,500 lines, no framework, no database, no network listener. The whole service is one blocking loop over SSH.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ autoscale.py                                                 │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  VMAutoscaler ......... config, main loop, decision routing  │</span></span>
<span class="line"><span>│  NotificationManager .. Gotify + SMTP fan-out                │</span></span>
<span class="line"><span>│  ConfigurationError ... raised on invalid startup config     │</span></span>
<span class="line"><span>└───────┬──────────────────────┬───────────────────┬───────────┘</span></span>
<span class="line"><span>        │                      │                   │</span></span>
<span class="line"><span>        ▼                      ▼                   ▼</span></span>
<span class="line"><span>┌───────────────┐   ┌──────────────────┐   ┌──────────────────┐</span></span>
<span class="line"><span>│ vm_manager.py │   │ host_resource_   │   │ billing_tracker  │</span></span>
<span class="line"><span>│               │   │ checker.py       │   │ .py              │</span></span>
<span class="line"><span>│ VMResource-   │   │                  │   │                  │</span></span>
<span class="line"><span>│ Manager       │   │ HostResource-    │   │ BillingTracker   │</span></span>
<span class="line"><span>│               │   │ Checker          │   │ SpecChangeRecord │</span></span>
<span class="line"><span>│ per-VM state, │   │                  │   │ StateChangeRec.  │</span></span>
<span class="line"><span>│ limits,       │   │ node CPU/RAM     │   │ BillingReport    │</span></span>
<span class="line"><span>│ cooldowns,    │   │ gate             │   │                  │</span></span>
<span class="line"><span>│ qm commands   │   │                  │   │ JSON state, CSV  │</span></span>
<span class="line"><span>└───────┬───────┘   └────────┬─────────┘   └──────────────────┘</span></span>
<span class="line"><span>        │                    │</span></span>
<span class="line"><span>        └────────┬───────────┘</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>        ┌──────────────────┐</span></span>
<span class="line"><span>        │ ssh_utils.py     │</span></span>
<span class="line"><span>        │                  │</span></span>
<span class="line"><span>        │ SSHClient        │</span></span>
<span class="line"><span>        │ connect / retry  │</span></span>
<span class="line"><span>        │ exec / close     │</span></span>
<span class="line"><span>        └────────┬─────────┘</span></span>
<span class="line"><span>                 │  SSH</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>        ┌──────────────────┐</span></span>
<span class="line"><span>        │ Proxmox VE node  │</span></span>
<span class="line"><span>        │ qm  ·  pvesh     │</span></span>
<span class="line"><span>        └──────────────────┘</span></span></code></pre></div><h2 id="control-flow" tabindex="-1">Control flow <a class="header-anchor" href="#control-flow" aria-label="Permalink to &quot;Control flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main()</span></span>
<span class="line"><span>└─ VMAutoscaler(config_path, logging_config_path)</span></span>
<span class="line"><span>   ├─ _load_config()          validate the four required sections</span></span>
<span class="line"><span>   ├─ _setup_logging()        logging_config.json wins over config.yaml</span></span>
<span class="line"><span>   ├─ NotificationManager()   validate channels, fail fast</span></span>
<span class="line"><span>   └─ BillingTracker()        only when billing.enabled</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VMAutoscaler.run()</span></span>
<span class="line"><span>└─ while True:</span></span>
<span class="line"><span>   └─ for host in proxmox_hosts:</span></span>
<span class="line"><span>      └─ for vm in virtual_machines where vm.proxmox_host == host.name</span></span>
<span class="line"><span>                                     and vm.scaling_enabled:</span></span>
<span class="line"><span>         └─ process_vm(host, vm)</span></span>
<span class="line"><span>            ├─ SSHClient(...).connect()</span></span>
<span class="line"><span>            ├─ _get_vm_manager(ssh, vm_id)    cached per VM</span></span>
<span class="line"><span>            ├─ vm_manager.is_vm_running()          → gate 1</span></span>
<span class="line"><span>            ├─ HostResourceChecker(...).check()    → gate 2</span></span>
<span class="line"><span>            ├─ vm_manager.get_resource_usage()</span></span>
<span class="line"><span>            ├─ _handle_cpu_scaling()   if cpu_scaling</span></span>
<span class="line"><span>            ├─ _handle_ram_scaling()   if ram_scaling</span></span>
<span class="line"><span>            └─ ssh_client.close()      always, in finally</span></span>
<span class="line"><span>      sleep(check_interval)</span></span></code></pre></div><h2 id="per-module-notes" tabindex="-1">Per-module notes <a class="header-anchor" href="#per-module-notes" aria-label="Permalink to &quot;Per-module notes&quot;">​</a></h2><h3 id="autoscale-py" tabindex="-1"><code>autoscale.py</code> <a class="header-anchor" href="#autoscale-py" aria-label="Permalink to &quot;\`autoscale.py\`&quot;">​</a></h3><p><code>VMAutoscaler</code> owns configuration, the loop and the routing of decisions; it does not talk to Proxmox itself. <code>_handle_cpu_scaling</code> and <code>_handle_ram_scaling</code> compare a usage figure against thresholds and call into the VM manager, then notify and record billing when the manager reports an actual change.</p><p><code>_get_vm_manager</code> caches one <code>VMResourceManager</code> per VMID for the lifetime of the process and rebinds it to each cycle&#39;s SSH client. That cache is what makes <code>scale_cooldown</code> meaningful across cycles and what keeps hotplug auto-configuration to a single check per VM.</p><p><code>NotificationManager</code> validates its configuration in the constructor, so a broken notification setup stops the service at startup rather than at the first interesting event.</p><h3 id="vm-manager-py" tabindex="-1"><code>vm_manager.py</code> <a class="header-anchor" href="#vm-manager-py" aria-label="Permalink to &quot;\`vm_manager.py\`&quot;">​</a></h3><p><code>VMResourceManager</code> is the only module that mutates anything. It holds:</p><ul><li><code>scale_cooldown</code> and one timestamp per resource (<code>cpu</code>, <code>ram</code>)</li><li>a <code>threading.Lock</code> guarding those timestamps</li><li>the config, for limit lookups</li></ul><p><code>can_scale(resource)</code> is a pure read; <code>_mark_scaled(resource)</code> starts a timer and is called only after a command has been issued. Limits resolve through <code>_scaling_limit</code>, which prefers the <code>scaling_limits</code> section and falls back to legacy flat keys.</p><h3 id="ssh-utils-py" tabindex="-1"><code>ssh_utils.py</code> <a class="header-anchor" href="#ssh-utils-py" aria-label="Permalink to &quot;\`ssh_utils.py\`&quot;">​</a></h3><p><code>SSHClient</code> wraps Paramiko. Connection: up to five attempts with exponential backoff, except authentication failures which raise immediately. Command execution: up to five attempts, closing and reconnecting between them, returning <code>(stdout, stderr, exit_status)</code>.</p><p>It is also a context manager, though <code>process_vm</code> uses explicit <code>connect()</code> / <code>close()</code> in a <code>try</code>/<code>finally</code> instead.</p><h3 id="host-resource-checker-py" tabindex="-1"><code>host_resource_checker.py</code> <a class="header-anchor" href="#host-resource-checker-py" aria-label="Permalink to &quot;\`host_resource_checker.py\`&quot;">​</a></h3><p>One method. Runs <code>pvesh get /nodes/$(hostname)/status --output-format json</code>, parses it, compares against the two ceilings, returns a boolean. Raises on JSON errors and missing fields — which surfaces as a per-VM <code>Error processing VM ...</code> rather than stopping the service.</p><h3 id="billing-tracker-py" tabindex="-1"><code>billing_tracker.py</code> <a class="header-anchor" href="#billing-tracker-py" aria-label="Permalink to &quot;\`billing_tracker.py\`&quot;">​</a></h3><p>Three dataclasses and a tracker. State is a single JSON file rewritten in full on every record. Reporting — period calculation, CSV export, webhooks — is complete API surface that the service does not currently call.</p><h2 id="threading-and-concurrency" tabindex="-1">Threading and concurrency <a class="header-anchor" href="#threading-and-concurrency" aria-label="Permalink to &quot;Threading and concurrency&quot;">​</a></h2><p>Effectively single-threaded. <code>threading.Lock</code> in <code>VMResourceManager</code> guards the cooldown timestamps, but nothing spawns a thread: hosts and VMs are processed sequentially, and each SSH command blocks.</p><p>Consequences:</p><ul><li>A slow or unreachable node stalls every VM behind it in the cycle. Five connection attempts with backoff is ~31 seconds; command retries add more.</li><li>Total cycle time grows linearly with the number of VMs.</li><li><code>check_interval</code> is a floor on the gap between cycles, not a period.</li></ul><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Lives in</th><th>Survives a restart?</th></tr></thead><tbody><tr><td>Configuration</td><td><code>config.yaml</code>, read once</td><td>n/a</td></tr><tr><td>Cooldown timestamps</td><td>Process memory</td><td><strong>No</strong></td></tr><tr><td>Cached VM managers</td><td>Process memory</td><td>No</td></tr><tr><td>SSH connections</td><td>Per VM, per cycle</td><td>No</td></tr><tr><td>Billing spec changes</td><td><code>billing_data.json</code></td><td>Yes</td></tr><tr><td>Logs</td><td><code>/var/log/vm_autoscale.log</code> + journal</td><td>Yes</td></tr></tbody></table><p>The only durable state the service writes is the billing file.</p><h2 id="error-handling" tabindex="-1">Error handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error handling&quot;">​</a></h2><p>Three layers:</p><ol><li><strong>Per operation</strong> — SSH connect and exec retry with backoff. Metric parse failures return <code>0.0</code> rather than raising, which is the source of the <a href="/proxmox-vm-autoscale/reference/limitations.html#metric-parsing-is-format-sensitive">silent scale-down</a> hazard.</li><li><strong>Per VM</strong> — <code>process_vm</code> wraps everything in <code>try</code>/<code>except</code>. A failure is logged, notified at priority 9, and the loop moves to the next VM. CPU and RAM scaling are additionally wrapped separately, so a CPU failure does not prevent the RAM evaluation.</li><li><strong>Per cycle</strong> — the main loop catches anything unexpected, notifies at priority 10, sleeps 60 seconds and continues. <code>KeyboardInterrupt</code> exits cleanly.</li></ol><p>The process only exits on a startup failure (<code>sys.exit(1)</code>) or <code>SIGINT</code>.</p><h2 id="extension-points" tabindex="-1">Extension points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension points&quot;">​</a></h2><p>Realistic places to add behaviour without restructuring:</p><table tabindex="0"><thead><tr><th>Goal</th><th>Where</th></tr></thead><tbody><tr><td>A new notification channel</td><td>Add a <code>send_*</code> method to <code>NotificationManager</code> and a branch in <code>send_notification</code></td></tr><tr><td>Different scaling arithmetic</td><td><code>VMResourceManager.scale_cpu</code> / <code>scale_ram</code></td></tr><tr><td>More metrics</td><td><code>get_resource_usage</code> and the <code>_parse_*</code> helpers</td></tr><tr><td>Per-VM thresholds</td><td><code>_handle_cpu_scaling</code> / <code>_handle_ram_scaling</code> already receive the VM dict&#39;s siblings; the plumbing to pass it is small</td></tr><tr><td>Scheduled billing reports</td><td>Call <code>BillingTracker.generate_period_report</code> from the main loop on a period boundary</td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p><code>tests/</code> holds 114 unit tests across five files, run with <code>pytest</code>. They use mocked SSH clients throughout — there is no integration test against a real Proxmox node, so anything depending on actual <code>pvesh</code> output format is unverified by CI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span></code></pre></div><p>CI runs the suite on Python 3.9–3.12 and <code>shellcheck -S warning</code> on <code>install.sh</code>.</p>`,40)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
